import {uploadKey} from './dataset-upload.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const done=new Set(['SUCCEEDED','CANCELED']);
export function transfersUI(store,toast){
  const section=document.querySelector('#page-transfers');let identity='',busy=false,generation=0,cursor=0;
  store.onAuthChange?.(()=>{generation++;identity='';busy=false;section.replaceChildren();});
  async function load(next=false){
    if(busy||!store.principal||!store.production||store.data?.transfers?.version!==1)return;busy=true;const token=generation;
    try{const result=await store.call('transfers.list',{cursor:next?cursor:0});if(token!==generation)return;cursor=result.nextCursor;const list=section.querySelector('#transfer-list');if(!next)list.replaceChildren();for(const row of result.transfers){const node=document.createElement('article'),r=row.result||{},bytes=r.bytes??(r.totalBytes!==undefined&&r.remainingBytes!==undefined?r.totalBytes-r.remainingBytes:0),total=r.totalBytes??row.snapshot?.totalBytes??row.manifest?.totalBytes??'?';node.className='panel';node.innerHTML=`<h3>${esc(row.name||row.reference?.dataset||'传输')} · ${esc(row.state)}</h3><p>${esc(row.owner?.name||row.owner?.username)} · ${esc(row.kind)} · ${esc(row.from?row.from+' → '+row.machine:row.machine)}</p><p><code>${esc(row.id)}</code> · ${esc(bytes)} / ${esc(total)} bytes</p><p>${esc(row.error||r.error||r.path||'')}</p><button type="button" data-transfer-action="status" data-id="${esc(row.id)}">核对状态</button> ${!done.has(row.state)?`<button type="button" data-transfer-action="cancel" data-id="${esc(row.id)}">终止（保留断点）</button>`:''} ${['FAILED','PAUSED'].includes(row.state)&&row.kind==='copy'&&!row.cancelRequested?`<button type="button" data-transfer-action="resume" data-id="${esc(row.id)}">恢复原任务</button>`:''}`;list.append(node);}section.querySelector('#transfer-more').hidden=!cursor;section.querySelector('#transfer-status').textContent='已读取；本机上传/下载断开后等待同一客户端续传。';}
    catch(e){if(token===generation)section.querySelector('#transfer-status').textContent=e.message;}finally{if(token===generation)busy=false;}
  }
  section.addEventListener('submit',async e=>{
    if(e.target.id!=='transfer-copy-form')return;e.preventDefault();if(busy)return;
    const form=e.target,values=new FormData(form),ref=String(values.get('reference')).split('@'),payload={kind:'copy',from:values.get('from'),machine:values.get('machine'),dataset:ref[0],version:ref[1],name:values.get('name')},account=store.principal?.userId;
    const requestKey=uploadKey(account,payload.from+'->'+payload.machine,payload.name,JSON.stringify([payload.dataset,payload.version]));e.submitter.disabled=true;const token=generation;
    try{const row=await store.call('transfers.create',{...payload,key:requestKey});if(token!==generation)return;toast('传输 '+row.id+' · '+row.state);await load();}catch(error){if(token===generation)toast(error.message);}finally{if(token===generation)e.submitter.disabled=false;}
  });
  section.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.id==='transfer-refresh')return load();if(b.id==='transfer-more')return load(true);if(!b.dataset.transferAction)return;if(b.dataset.transferAction==='cancel'&&!window.confirm('终止这一项传输？保留未完成文件，不会自动重启。'))return;b.disabled=true;const token=generation;try{await store.call('transfers.'+b.dataset.transferAction,{id:b.dataset.id});if(token===generation)await load();}catch(error){if(token===generation)toast(error.message);}finally{if(token===generation)b.disabled=false;}});
  return active=>{
    const next=store.principal?JSON.stringify([store.authGeneration,store.principal.userId,(store.data?.machines||[]).map(m=>m.id)]):'';
    if(next!==identity){identity=next;generation++;busy=false;const enabled=store.production&&store.data?.transfers?.version===1,options=(store.data?.machines||[]).map(m=>`<option value="${esc(m.id)}">${esc(m.name||m.id)}</option>`).join('');section.innerHTML=`<p>服务器之间的固定数据集版本在 LAN 后台传输，不占 GPU；关闭页面不会停止。原有代码 sync 仍是手动客户端同步。</p><p>上传目录请使用“数据集”；下载及命令行操作：<code>gpuctl transfer --help</code>。长训练使用 run，无需 tmux 保活；网页交互终端仍有时限。</p><form id="transfer-copy-form" class="panel"><h3>服务器间传输</h3><label>源服务器<select name="from">${options}</select></label><label>目标服务器<select name="machine">${options}</select></label><label>固定数据集<input name="reference" placeholder="NAME@完整64位版本" required></label><label>目标私有数据集名称<input name="name" pattern="[A-Za-z0-9][A-Za-z0-9_-]{0,39}" required></label><button type="submit" ${enabled?'':'disabled'}>后台开始传输</button></form><p id="transfer-status" role="status">${enabled?'刷新可查看已有任务。':'当前为演示或旧后台，未启用真实传输。'}</p><button id="transfer-refresh" ${enabled?'':'disabled'}>刷新传输列表</button><div id="transfer-list"></div><button id="transfer-more" hidden>下一页</button>`;}
    if(active&&!busy&&section.querySelector('#transfer-list')?.childElementCount===0)load();
  };
}
